// План specs/rbac.md 1.1–1.2 (тикет #04d338, реджект №2 п. 2.2–2.3). PROD, компания «test», десктоп, EN. Две роли: владелец (admin) шлёт приглашение, гость открывает ссылку.
// @writes: создаёт приглашение QA-…@example.test (письмо на example.test уходит в никуда) и в finally отзывает его. Регистрация до конца — не автоматизируется (пароль вводит человек).
import { test, expect } from '../../fixtures';
import { Page } from '@playwright/test';
import { openTeam, prepare, prepareGuest, teamRow } from './rbac-helpers';

test.describe('RBAC — invitation page (#04d338)', () => {
  test('QA-AUTO: invitation link opens "Join test on Techory" with a locked email; ?email= spoof does not change the invited address #04d338 @desktop @writes', async ({ asUser }) => {
    test.setTimeout(120_000);
    const owner = await asUser('admin');
    const guest = await asUser('guest');
    await prepare(owner);
    await prepareGuest(guest);
    const invited = `qa-invite-${Date.now().toString(36)}@example.test`;
    try {
      // Владелец: Invite a member → роль по умолчанию Admin-dispatcher → Send invitation
      await owner.context().grantPermissions(['clipboard-read', 'clipboard-write']);
      await openTeam(owner);
      await owner.getByRole('button', { name: 'Invite a member' }).click();
      const dialog = owner.getByRole('dialog');
      await expect(dialog.getByText('Invite a team member')).toBeVisible();
      await dialog.getByLabel('Email').fill(invited);
      await dialog.getByRole('button', { name: 'Send invitation' }).click();
      const row = teamRow(owner, invited);
      await expect(row, 'приглашённый в списке со статусом Invited').toContainText('Invited', { timeout: 30_000 });

      // Ссылка приглашения — «…» в строке → Copy invitation link → буфер обмена
      await row.getByRole('button').last().click();
      await owner.getByRole('menuitem', { name: /Copy invitation link/i }).click();
      const link = await owner.evaluate(() => navigator.clipboard.readText());
      expect(link, 'скопирована ссылка приглашения').toMatch(/^https?:\/\/.+\/register\?.*invite=/);

      // Гость: заголовок, роль, email заблокирован и равен адресу приглашения (источник: реджект №2 «Join test on Techory», email предзаполнен и заблокирован)
      await guest.goto(link);
      await expect(guest.getByRole('heading', { name: 'Join test on Techory' })).toBeVisible({ timeout: 30_000 });
      await expect(guest.getByText('You were invited as Admin-dispatcher')).toBeVisible();
      await expect(guest.getByText(/Company Admin Sign-Up|Create your workspace/i)).toHaveCount(0);
      await expectLockedEmail(guest, invited);

      // Подмена ?email= в адресе: адрес приглашения не меняется (находка 17.11: 180–240 мс виден адрес из URL — поэтому ждём устойчивого значения)
      const spoofed = new URL(link);
      spoofed.searchParams.set('email', 'qa-spoof@example.test');
      await guest.goto(spoofed.toString());
      await expect(guest.getByRole('heading', { name: 'Join test on Techory' })).toBeVisible({ timeout: 30_000 });
      await expectLockedEmail(guest, invited);
      await expect(guest.getByRole('textbox', { name: /^email/i })).not.toHaveValue('qa-spoof@example.test');
    } finally {
      await revokeInvite(owner, invited);
    }
  });

  test('QA-AUTO: registering through an invitation completes without email verification and joins the inviter company #04d338 @desktop @writes', async () => {
    test.skip(true, 'Регистрация до конца требует пароль — его вводит человек (правило проекта). Проверено вручную 17.11 только до формы; отправка регистрации, вход без верификации и адрес с существующим аккаунтом — не проверялись.');
  });
});

async function expectLockedEmail(page: Page, email: string) {
  const field = page.getByRole('textbox', { name: /^email/i }).or(page.getByLabel('Email')).first();
  await expect(field, 'email приглашения в поле').toHaveValue(email, { timeout: 15_000 });
  await expect(field).toHaveAttribute('aria-readonly', 'true');
  await expect(page.getByText('The invitation was sent to this address, so the login uses it.')).toBeVisible();
}

/** Очистка (не роняет тест): «…» в строке приглашённого → отзыв приглашения → подтверждение. */
async function revokeInvite(page: Page, email: string) {
  if (page.isClosed()) return;
  try {
    await openTeam(page);
    const row = teamRow(page, email);
    if (!(await row.count())) return;
    await row.getByRole('button').last().click();
    await page.getByRole('menuitem', { name: /revoke|cancel invitation|cancel invite|remove|delete/i }).first().click();
    const confirm = page.getByRole('alertdialog').or(page.getByRole('dialog')).getByRole('button', { name: /^(Revoke|Cancel invitation|Remove|Delete|Confirm|Yes)/i });
    if (await confirm.count()) await confirm.first().click();
    await expect(teamRow(page, email)).toHaveCount(0, { timeout: 15_000 });
  } catch (e) {
    console.warn(`очистка: приглашение ${email} не отозвано — отозвать вручную на /Team: ${String(e).slice(0, 200)}`);
  }
}
